ProbabilityTheory.IsPoissonRandomMeasure.lintegral_exp_neg_lintegral.{u_1, u_2} {Ω : Type u_1}
  {E : Type u_2} {mΩ : MeasurableSpace Ω} [MeasurableSpace E] {N : Ω → MeasureTheory.Measure E}
  {ν : MeasureTheory.Measure E} {P : MeasureTheory.Measure Ω}
  (hN : ProbabilityTheory.IsPoissonRandomMeasure N ν P) [MeasureTheory.SigmaFinite ν]
  {f : E → ENNReal} (hf : Measurable f) :
  ∫⁻ (ω : Ω), (-↑(∫⁻ (x : E), f x ∂N ω)).exp ∂P = (-↑(∫⁻ (x : E), 1 - (-↑(f x)).exp ∂ν)).exp

ProbabilityTheory.IsPoissonRandomMeasure.isSimpleMaxStable_map_process.{u_1, u_2, u_3, u_4}
  {S : Type u_1} {T : Type u_2} [MeasurableSpace S] {Ω : Type u_3} {mΩ : MeasurableSpace Ω}
  {P : MeasureTheory.Measure Ω} {N : Ω → MeasureTheory.Measure (ℝ × S)}
  {μ : MeasureTheory.Measure S} {W : T → S → ENNReal} [MeasureTheory.SFinite μ]
  (hN : ProbabilityTheory.IsPoissonRandomMeasure N ((ExtremeValueTheory.radialMeasure 1).prod μ) P)
  (hW : ∀ (t : T), Measurable (W t)) (hW1 : ∀ (t : T), ∫⁻ (s : S), W t s ∂μ = 1) {ι : Type u_4}
  [Fintype ι] (t : ι → T) :
  ExtremeValueTheory.IsSimpleMaxStable
    (MeasureTheory.Measure.map (fun ω i => ExtremeValueTheory.spectralVector W (N ω) (t i)) P)
